import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 500;
    static int modulus;
    static int[][] comb = new int[MAX_SIZE + 1][MAX_SIZE + 1];
    static Pair[] dp1_state = new Pair[MAX_SIZE + 1];
    static Pair[][][] dp2_state = new Pair[2][MAX_SIZE + 1][MAX_SIZE + 1];

    static class Pair {
        long first;
        long second;

        Pair() {
            this.first = 0;
            this.second = 0;
        }
    }

    static void add_mod(long[] x, long y) {
        x[0] += y;
        if (x[0] >= modulus) {
            x[0] -= modulus;
        }
    }

    static long sum_series(int n) {
        return (long) n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        modulus = sc.nextInt();

        for (int i = 0; i <= m; ++i) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                comb[i][j] = comb[i - 1][j] + comb[i - 1][j - 1];
                if (comb[i][j] >= modulus) {
                    comb[i][j] -= modulus;
                }
            }
        }

        for (int i = 0; i <= m; ++i) {
            dp1_state[i] = new Pair();
        }
        dp1_state[0].first = 1;

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= i; ++j) {
                long w = (dp1_state[j - 1].first * dp1_state[i - j].first) % modulus;
                w = (w * comb[i - 1][j - 1]) % modulus;

                long[] tempSecond = {dp1_state[i].second};
                long sumVal = (sum_series(j - 1) + sum_series(i - j)) % modulus;
                add_mod(tempSecond, (sumVal * w) % modulus);

                long[] tempSecond2 = {dp1_state[i].second};
                long val1 = (dp1_state[j - 1].second * dp1_state[i - j].first) % modulus;
                val1 = (val1 * (i + 1)) % modulus;
                val1 = (val1 * comb[i - 1][j - 1]) % modulus;
                add_mod(tempSecond2, val1);

                long[] tempSecond3 = {dp1_state[i].second};
                long val2 = (dp1_state[j - 1].first * dp1_state[i - j].second) % modulus;
                val2 = (val2 * (i + 1)) % modulus;
                val2 = (val2 * comb[i - 1][j - 1]) % modulus;
                add_mod(tempSecond3, val2);

                dp1_state[i].first = (dp1_state[i].first + w) % modulus;
                dp1_state[i].second = (tempSecond[0] + tempSecond2[0] + tempSecond3[0]) % modulus;
            }
        }

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                dp2_state[0][i][j] = new Pair();
                dp2_state[1][i][j] = new Pair();
            }
        }

        dp2_state[0][0][0].first = 1;
        dp2_state[1][0][0].first = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= i; ++j) {
                for (int ln = 1; ln <= n - i; ++ln) {
                    // Update dp2_state[1][i + ln][j]
                    add_mod(new long[]{dp2_state[1][i + ln][j].first}, dp2_state[0][i][j].first);
                    add_mod(new long[]{dp2_state[1][i + ln][j].second}, dp2_state[0][i][j].second);

                    // Update dp2_state[0][i + ln][j + ln]
                    long val1 = (dp2_state[1][i][j].first * dp1_state[ln].first) % modulus;
                    val1 = (val1 * comb[j + ln][j]) % modulus;
                    add_mod(new long[]{dp2_state[0][i + ln][j + ln].first}, val1);

                    long val2 = (dp2_state[1][i][j].first * dp1_state[ln].second) % modulus;
                    val2 = (val2 * comb[j + ln][j]) % modulus;
                    add_mod(new long[]{dp2_state[0][i + ln][j + ln].second}, val2);

                    long val3 = (dp2_state[1][i][j].second * dp1_state[ln].first) % modulus;
                    val3 = (val3 * comb[j + ln][j]) % modulus;
                    add_mod(new long[]{dp2_state[0][i + ln][j + ln].second}, val3);
                }
            }
        }

        long final_result = (dp2_state[0][n][m].second + dp2_state[1][n][m].second) % modulus;
        System.out.println(final_result);
        sc.close();
    }
}

